/* Happy navigation: base screens, bottom cards, and contextual exercise add. */
let baseView='diary',panelStack=[],currentExerciseId=null;
const pullVariantIds=['pull-up','chin-up','pull-up-narrow','pull-up-wide','chin-up-narrow','chin-up-wide'];
for(const base of ['pull-up','chin-up'])for(const width of ['narrow','wide']){const ex=SEED.exercises.find(e=>e.id===base);if(ex&&!SEED.exercises.some(e=>e.id===base+'-'+width))SEED.exercises.push({...clone(ex),id:base+'-'+width,name:ex.name+' · '+(width==='narrow'?'узкий':'широкий')+' хват',aliases:[...(ex.aliases||[]),width==='narrow'?'узкий хват':'широкий хват']})}
function pullFrameUrl(id){return './exercises/pull-up.html?grip='+(id.startsWith('chin-up')?'underhand':'overhand')+'&width='+(id.endsWith('-narrow')?'narrow':id.endsWith('-wide')?'wide':'medium')}
const navAssets=__NAV_ICONS__;
const oldProfile=renderProfile,oldPersist=persist,oldExerciseDetails=showExercise;
document.querySelector('.app').insertAdjacentHTML('afterend','<div id="panel-root"></div>');
const activePanel=()=>panelStack.at(-1);
function gripButton(action){return `<button class="grip" data-action="${action}" aria-label="Закрыть карточку — потяни вниз или нажми"></button>`}
function closePanel(){closeSheet();panelStack.pop();view=activePanel()?.type||baseView;currentExerciseId=activePanel()?.exerciseId||null;render()}
function openPanel(panel){closeSheet();if(activePanel()?.type===panel.type&&activePanel()?.id===panel.id)panelStack.pop();panelStack.push(panel);view=panel.type;currentExerciseId=panel.exerciseId||null;render()}
goto=function(v){closeSheet();if(v==='active'||v==='detail'){panelStack=[];openPanel({type:v,id:v==='detail'?detailId:'active'});return}baseView=v==='settings'?'profile':v;panelStack=[];view=baseView;currentExerciseId=null;render();window.scrollTo({top:0,behavior:'instant'})};
backTop=function(title){return `<h1 class="view-title">${esc(title)}</h1>`};
renderTop=function(title,date=true){return `<header class="top"><h1>${esc(title)}</h1>${date?`<label class="date-pill">${navAssets.day}<span>${dateLabel(selectedDate)}</span><input aria-label="День дневника" type="date" value="${selectedDate}" id="day-picker"></label>`:''}</header>`};
nav=function(){const chosen=baseView;$('#dock').innerHTML='<div class="dockBg" id="dockBg"></div><svg class="dockEdge" id="dockEdge" preserveAspectRatio="none" aria-hidden="true"><path></path></svg>'+[['diary','day','Дневник'],['journal','trends','Журнал'],null,['library','catalog','Библиотека'],['profile','settings','Настройки']].map(i=>i?`<button class="tab ${chosen===i[0]?'on':''}" data-action="navigate" data-view="${i[0]}" aria-current="${chosen===i[0]?'page':'false'}">${navAssets[i[1]]}<span>${i[2]}</span></button>`:'<span class="gap"></span>').join('')+`<button class="dockFab" id="sport-fab" data-action="voice" aria-label="Записать голосом или текстом">${icon('microphone')}</button>`;shapeDock();$('#active-banner').innerHTML=state.active&&!panelStack.length?`<div class="active-banner"><span class="row">${icon('timer')}<b style="font-size:12px">${esc(state.active.title)}</b></span><button data-action="resume">Продолжить</button></div>`:''};
const legacyDiary=renderDiary;
renderDiary=function(){const html=legacyDiary().replaceAll(icon('caret-right'),'');const p=document.createElement('div');p.innerHTML=html;p.querySelector('h1').textContent='Тренировки';const pins=p.querySelector('.pin-grid');if(pins){pins.className='section-list';pins.innerHTML=[['sea','waves','Плавание в море'],['gym','barbell','Тренажёрный зал'],['bars','person-simple','Турники']].map(([k,i,t])=>{const all=state.workouts.filter(w=>w.kind===k).sort((a,b)=>b.start.localeCompare(a.start)),today=all.filter(w=>w.start.slice(0,10)===selectedDate);return `<button class="card section-row" data-action="sport-section" data-id="${k}"><span class="symbol">${icon(i)}</span><span><b>${t}</b><small>${today.length?today.length+' · '+durationText(today.reduce((n,w)=>n+w.duration,0)):all.length?'Последняя · '+dateLabel(all[0].start.slice(0,10)):'Пока нет записей'}</small></span></button>`}).join('')}p.querySelectorAll('svg.icon').forEach(el=>{if(el.outerHTML===icon('caret-right'))el.remove()});const firstTitle=p.querySelector('.section-title');if(firstTitle)firstTitle.querySelector('h2').textContent='Мои разделы';return p.innerHTML};
const legacyWorkoutCard=workoutCard;
workoutCard=function(w,d){return legacyWorkoutCard(w,d).replaceAll(icon('caret-right'),'')};
const legacyExerciseCard=exerciseCard;
exerciseCard=function(e,a){return legacyExerciseCard(e,a).replaceAll(icon('caret-right'),'')};
previewTemplate=function(id){openPanel({type:'template',id})};
showExercise=function(id){if(!exercise(id))return;currentExerciseId=id;openPanel({type:'exercise',id,exerciseId:id})};
function renderSection(id){const t=templates().find(t=>t.id===id);return `<div class="training-heading"><h1 class="view-title">${esc(t?.title||'Тренировки')}</h1><button class="text-btn" data-action="edit-template" data-id="${esc(id)}">${icon('pencil-simple')} Редактировать</button></div><button class="button primary" data-action="start" data-id="${id}">${icon('play')} Начать тренировку</button>${renderTemplateItems(t)}`}

function renderTemplateItems(t){return Object.entries(phaseNames).map(([p,n])=>`<div class="phase-heading"><strong>${n}</strong></div><div class="card">${t?.items.filter(x=>x[1]===p).map(([eid,_,sets])=>`<button class="inline-exercise" data-action="exercise-detail" data-id="${eid}"><b>${esc(exercise(eid)?.name||eid)}</b><small>${sets} подх.</small></button>`).join('')||'<span class="sub">Пока пусто</span>'}</div>`).join('')}
function renderTemplateCard(id){const t=templates().find(t=>t.id===id);return `<div class="training-heading"><h1 class="view-title">${esc(t.title)}</h1><button class="text-btn" data-action="edit-template" data-id="${esc(id)}">${icon('pencil-simple')} Редактировать</button></div><button class="button primary" style="margin-top:16px" data-action="start" data-id="${esc(id)}">${icon('play')} Начать тренировку</button>${renderTemplateItems(t)}`}

function genericExercise(id){const e=exercise(id);return `<div style="padding:8px 20px 30px;overflow:auto;height:100%"><div class="skeleton-hero">${icon('image')}<span>Визуализация пока не добавлена</span><div class="skeleton-steps"><span>01 · Старт</span><span>02 · Движение</span><span>03 · Завершение</span></div></div><div class="card" style="margin-bottom:16px"><h3>Варианты</h3><p class="sheet-info">Варианты ещё не добавлены.</p></div><div class="card"><h3>Техника</h3><p class="sheet-info">Описание ещё не заполнено.</p></div><button class="button" data-action="exercise-stats" data-id="${id}" style="margin-top:15px">${icon('chart-line-up')} Моя динамика</button>${e.scope==='user'?`<button class="button" data-action="custom-exercise" data-id="${id}" style="margin-top:10px">${icon('pencil-simple')} Изменить упражнение</button>`:''}</div>`}
function renderPanel(){const p=activePanel(),root=$('#panel-root');document.querySelector('.app').inert=!!p;const panelKey=p?`${p.type}:${p.id}`:'';const isNew=root.dataset.panelKey!==panelKey;root.dataset.panelKey=panelKey;if(!p){root.innerHTML='';document.body.classList.remove('panel-open');return}document.body.classList.add('panel-open');let content='',extra='';if(p.type==='exercise'){currentExerciseId=p.exerciseId||p.id;extra=' exercise-panel';content=pullVariantIds.includes(p.id)?`<iframe class="exercise-frame" title="Подтягивания: техника и варианты хвата" src="${pullFrameUrl(currentExerciseId)}"></iframe>`:genericExercise(p.id)}else if(p.type==='section')content=renderSection(p.id);else if(p.type==='template')content=renderTemplateCard(p.id);else if(p.type==='active')content=renderActive();else if(p.type==='detail'){detailId=p.id;content=renderDetail()}root.innerHTML=`<section class="panel-screen${extra}${isNew?' entering':''}" aria-label="Карточка ${p.type==='exercise'?'упражнения':'тренировки'}">${gripButton('close-panel')}${p.type==='exercise'?exerciseActions():''}<div class="panel-body">${content}</div></section>`;wireGrip(root.querySelector('.grip'),root.querySelector('.panel-screen'),closePanel,true)}
render=function(){const samePanel=$('#panel-root').dataset.panelKey===(activePanel()?`${activePanel().type}:${activePanel().id}`:'');const pos=samePanel?$('.panel-body')?.scrollTop||0:0;$('#page').innerHTML=({diary:renderDiary,library:renderLibrary,journal:renderJournal,profile:renderProfile}[baseView]||renderDiary)();renderPanel();if($('.panel-body'))$('.panel-body').scrollTop=pos;nav();updateClock();if(typeof paintHappyAccount==='function')paintHappyAccount()};
openSheet=function(title,html,kind=''){priorFocus=document.activeElement;sheetKind=kind;$('#modal-root').innerHTML=`<div class="overlay" id="overlay"><section class="sheet" role="dialog" aria-modal="true" aria-labelledby="sheet-title">${gripButton('close')}<div class="sheet-top"><h2 id="sheet-title">${esc(title)}</h2>${kind==='assign'?exerciseFavoriteButton():''}</div>${html}</section></div>`;document.body.style.overflow='hidden';$('.sheet .grip').focus();wireGrip($('.sheet .grip'),$('.sheet'),closeSheet,false);$('#overlay').addEventListener('click',e=>{if(e.target.id==='overlay')closeSheet()})};
function exerciseFavoriteButton(){const selected=(state.favoriteExercises||[]).includes(currentExerciseId);return `<button type="button" class="favorite-star ${selected?'selected':''}" data-action="favorite-exercise" aria-label="${selected?'Убрать упражнение из избранного':'Добавить упражнение в избранное'}" aria-pressed="${selected}"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m12 3 2.8 5.7 6.3.9-4.55 4.43 1.07 6.27L12 17.34l-5.62 2.96 1.07-6.27L2.9 9.6l6.3-.9Z"/></svg></button>`}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action="favorite-exercise"]');if(!b||!exercise(currentExerciseId))return;const ids=new Set(state.favoriteExercises||[]);if(ids.has(currentExerciseId))ids.delete(currentExerciseId);else ids.add(currentExerciseId);state.favoriteExercises=[...ids];persist();b.outerHTML=exerciseFavoriteButton();if($('#library-results'))$('#library-results').innerHTML=libraryResults()});
function wireGrip(handle,card,onClose,panel){let startY=null,dy=0,moved=false;handle.addEventListener('pointerdown',e=>{startY=e.clientY;dy=0;moved=false;handle.setPointerCapture(e.pointerId);card.style.transition='none'});handle.addEventListener('pointermove',e=>{if(startY===null)return;dy=Math.max(0,e.clientY-startY);moved=dy>5;card.style.transform=panel?`translate(-50%,${dy}px)`:`translateY(${dy}px)`});const end=e=>{if(startY===null)return;startY=null;card.style.transition='transform .2s ease';if(dy>70){handle.dataset.swiped='1';onClose()}else{card.style.transform=panel?'translate(-50%,0)':'translateY(0)';if(moved){handle.dataset.swiped='1';setTimeout(()=>delete handle.dataset.swiped,0)}}};handle.addEventListener('pointerup',end);handle.addEventListener('pointercancel',()=>{startY=null;card.style.transition='transform .2s ease';card.style.transform=panel?'translate(-50%,0)':'translateY(0)'})}
function exerciseActions(){return `<div class="exercise-heading"><h1 class="view-title">${esc(exercise(currentExerciseId)?.name||'')}</h1><div class="exercise-actions"><button class="text-btn" data-action="assign-exercise">Добавить</button><button class="text-btn share-icon" data-action="share-exercise" aria-label="Поделиться упражнением"><svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 15V3m-4 4 4-4 4 4M7 10H5v11h14V10h-2"/></svg></button></div></div>`}

function assignExercise(){const e=exercise(currentExerciseId);if(!e)return;const mine=templates().filter(t=>!t.recommended);openSheet('Добавить',`<form id="assign-form" data-id="${esc(e.id)}"><input type="hidden" name="destination" value="current"><div class="assign-options"><button class="button" type="submit">${state.active?'В текущую тренировку':'В новую тренировку'}</button><select name="template" aria-label="Добавить в мою тренировку" ${mine.length?'':'disabled'}><option value="" selected disabled>В мою тренировку</option>${mine.map(t=>`<option value="${esc(t.id)}">${esc(t.title)}</option>`).join('')}</select></div></form>`,'assign')}
async function shareExercise(){const e=exercise(currentExerciseId);if(!e)return;const url=new URL(location.pathname,location.origin);url.searchParams.set('exercise',e.id);if(navigator.share){try{await navigator.share({title:e.name,url:url.href});return}catch(err){if(err.name==='AbortError')return}}try{await navigator.clipboard.writeText(url.href);toast('Ссылка на упражнение скопирована')}catch{openSheet('Поделиться упражнением',`<label class="field">Ссылка<input readonly aria-label="Ссылка на упражнение" value="${esc(url.href)}"></label>`)}}
document.addEventListener('change',e=>{if(!e.target.matches('#assign-form select[name=template]')||!e.target.value)return;const form=e.target.form;form.elements.destination.value='template';form.requestSubmit()});
document.addEventListener('click',e=>{if(e.target.closest('[data-action="share-exercise"]'))shareExercise()});

renderProfile=function(){return '<div class="happy-settings">'+renderTop('Настройки',false)+`<section class="happy-section" data-happy-section="account"><h2 class="happy-heading">Аккаунт</h2><div class="happy-card" id="happy-account"></div>${HappyUI.accountNote()}</section><section class="happy-section" data-happy-section="backup"><h2 class="happy-heading">Резервная копия</h2>__HAPPY_SPORT_BACKUP__</section><section class="happy-section" data-happy-section="links"><h2 class="happy-heading">Связанные приложения</h2><div class="happy-card"><div class="happy-actions"><a class="happy-button" href="https://astamurberlin-rgb.github.io/happyamurio/day/">Happy Day</a><a class="happy-button" href="https://astamurberlin-rgb.github.io/happyamurio/meal/">Happy Meal</a></div></div></section><h2 class="happy-heading">Настройки тренировок</h2><div class="settings-section">Датчики</div><div class="card"><div class="setting-row"><div><b>Apple Здоровье</b><small>Нужна нативная интеграция</small></div><button class="text-btn" data-action="connections">Подробнее</button></div><div class="setting-row"><div><b>Пульс</b><small>Демонстрация шкалы во время тренировки</small></div><input class="toggle" id="demo-pulse" type="checkbox" aria-label="Демонстрация пульса" ${state.demoPulse?'checked':''}></div></div><div class="settings-section">Мои данные</div><div class="card"><div class="setting-row"><b>Тренировки</b><span>${state.workouts.length}</span></div><div class="setting-row"><b>Замеры</b><span>${state.measurements.length}</span></div></div></div>`};
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;if(b.dataset.swiped){e.stopImmediatePropagation();return}const a=b.dataset.action,id=b.dataset.id;if(['close-panel','sport-section','section-past','assign-exercise','exercise-stats'].includes(a)){e.stopImmediatePropagation();if(a==='close-panel')closePanel();if(a==='sport-section')openPanel({type:'section',id});if(a==='section-past'){showWorkoutForm('past');const f=$('#workout-form');f.elements.kind.value=id;f.elements.title.value=templates().find(t=>t.id===id).title}if(a==='assign-exercise')assignExercise();if(a==='exercise-stats')openExerciseHistory(id)}},true);
document.addEventListener('submit',e=>{if(e.target.id!=='assign-form')return;e.preventDefault();e.stopImmediatePropagation();const f=new FormData(e.target),id=e.target.dataset.id,ex=exercise(id),phase=['warmup','cooldown'].includes(librarySport)?librarySport:'main';if(f.get('destination')==='template'){const t=clone(templates().find(t=>t.id===f.get('template')));t.items.push([id,phase,1]);if(baseTemplates.some(x=>x.id===t.id)){state.templateOverrides??={};state.templateOverrides[t.id]=t}else state.templates[state.templates.findIndex(x=>x.id===t.id)]=t;persist();closeSheet();toast('Добавлено в «'+t.title+'»: '+ex.name)}else{closeSheet();if(!state.active)startWorkout();state.active.exercises.push({id,name:ex.name,phase,notes:'',sets:[blankSet(ex,phase)]});persist();goto('active');toast(ex.name+' добавлено')}} ,true);
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#overlay')&&activePanel()){e.preventDefault();closePanel()}});
window.addEventListener('message',e=>{const frame=$('.exercise-frame');if(!frame||e.source!==frame.contentWindow||e.origin!==location.origin||!['happy-sport.exercise-variant','happy-sport.exercise-add'].includes(e.data?.type)||!pullVariantIds.includes(e.data.exerciseId))return;currentExerciseId=e.data.exerciseId;activePanel().exerciseId=currentExerciseId;const heading=$('.exercise-heading h1');if(heading)heading.textContent=exercise(currentExerciseId)?.name||'';nav();if(e.data.type==='happy-sport.exercise-add')assignExercise()});
window.addEventListener('resize',()=>shapeDock());
render();
